-- BL-072: curated landing catalog membership lives in the database instead of a Java list.
-- status controls landing/search membership only; inactive never touches books or generated art.
-- Seeded from the former CuratedCatalogService list (all active).
CREATE TABLE curated_books (
    id VARCHAR(255) PRIMARY KEY,
    source VARCHAR(32) NOT NULL,
    source_id VARCHAR(64) NOT NULL,
    title VARCHAR(512) NOT NULL,
    author VARCHAR(512) NOT NULL,
    popularity INTEGER NOT NULL,
    subjects_json TEXT NOT NULL,
    bookshelves_json TEXT NOT NULL,
    aliases_json TEXT NOT NULL,
    status VARCHAR(16) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT uk_curated_books_source UNIQUE (source, source_id),
    CONSTRAINT ck_curated_books_status CHECK (status IN ('active', 'inactive'))
);

